BEGIN;

DELETE FROM public.packages;

ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, city = EXCLUDED.city, state = EXCLUDED.state, country = EXCLUDED.country, lat = EXCLUDED.lat, lng = EXCLUDED.lng, description = EXCLUDED.description, updated_at = now();

ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, genre = EXCLUDED.genre, subgenre = EXCLUDED.subgenre, description = EXCLUDED.description, updated_at = now();

ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, city = EXCLUDED.city, state = EXCLUDED.state, country = EXCLUDED.country, venue_type = EXCLUDED.venue_type, active = EXCLUDED.active, updated_at = now();

